import { useTranslation } from 'react-i18next';
import { usePageContext } from 'vike-react/usePageContext';
import { Center, Stack } from 'styled-system/jsx';
import { Heading } from '~/components/ui/heading';
import { Link } from '~/components/ui/link';

export { Page };

function Page() {
  const { t } = useTranslation();
  const pageContext = usePageContext();

  let msg: string; // Message shown to the user
  const { abortReason, abortStatusCode } = pageContext ?? {};
  if (typeof abortReason === 'string') {
    msg = abortReason;
  } else if (abortStatusCode === 403) {
    msg = t('error_page.access_denied');
  } else if (abortStatusCode === 401) {
    msg = t('error_page.login_required');
  } else {
    msg = pageContext?.is404
      ? t('error_page.page_not_found')
      : t('error_page.something_went_wrong');
  }

  return (
    <Center w="100vw" h="100dvh">
      <Stack alignItems="center">
        <Heading fontSize="xl">{msg}</Heading>
        <Link href="/">{t('error_page.go_back')}</Link>
      </Stack>
    </Center>
  );
}
